// CKZG4844.java:computeCellsAndProofs (lines 167-179)
@Override
public List<KZGCellAndProof> computeCellsAndProofs(final Bytes blob) {
    final CellsAndProofs cellsAndProofs = CKZG4844JNI.computeCellsAndKzgProofs(blob.toArrayUnsafe());
    final List<KZGCell> cells = KZGCell.splitBytes(Bytes.wrap(cellsAndProofs.getCells()));
    final List<KZGProof> proofs = KZGProof.splitBytes(Bytes.wrap(cellsAndProofs.getProofs()));
    if (cells.size() != proofs.size()) { throw new KZGException("Cells and proofs size differ"); }
    return IntStream.range(0, cells.size()).mapToObj(i -> new KZGCellAndProof(cells.get(i), proofs.get(i))).toList();
}
